                        put("url", json.encodeToJsonElement(serializer<String>(), value.url))
                        put("local_page", json.encodeToJsonElement(serializer<Boolean>(), value.localPage))
                    },
                ),
            )
            is AskBody.Access -> JsonObject(
                mapOf(
                    "Access" to buildJsonObject {
                        put("reason", json.encodeToJsonElement(serializer<String>(), value.reason))
                        put("read", json.encodeToJsonElement(serializer<List<String>>(), value.read))
                        put("write", json.encodeToJsonElement(serializer<List<String>>(), value.write))
                        put("network", json.encodeToJsonElement(serializer<Boolean>(), value.network))
                        put("hosts", json.encodeToJsonElement(serializer<List<String>>(), value.hosts))
                    },
                ),
            )
            is AskBody.Unanswerable -> JsonObject(
                mapOf(
                    "Unanswerable" to buildJsonObject {
                        put("reason", json.encodeToJsonElement(serializer<String>(), value.reason))
                    },
                ),
            )
        }
        jsonEncoder.encodeJsonElement(element)
    }
}

@Serializable
data class AskCard(
    @SerialName("kind") val kind: Kind,
    /** What an answer names. */
    @SerialName("key") val key: String,
    /**
     * The item the ask points at: the call it would let run, or the row of
     * an ask that is the work.
     */
    @SerialName("item_key") val itemKey: String,
    /** "1 of 3" when asks are queued. */
    @SerialName("position") val position: Long,
    @SerialName("count") val count: Long,
    @SerialName("body") val body: AskBody,
    /** The likely choice first. Only what this agent offers. */
    @SerialName("choices") val choices: List<Choice>,
    /**
     * A note may go out with each question's answer. Not for the
     * provider's own dialogs, answered on its screen.
     */
    @SerialName("question_note") val questionNote: Boolean,
    /**
     * A question may be left unanswered. Not for the provider's own
     * dialogs either.
     */
    @SerialName("question_skip") val questionSkip: Boolean,
    /**
     * The person may reply in their own words instead of answering the
     * questions. Not for the provider's own dialogs, outside any turn.
     */
    @SerialName("question_reply") val questionReply: Boolean,
    /**
     * Stopping interrupts a running turn. Codex proposes a plan as its
     * turn ends, so with its plan open there is no turn to stop.
     */
    @SerialName("stops_turn") val stopsTurn: Boolean,
    /**
     * Approving must be deliberate: a keyboard view opens the card on its
     * refusal and takes no digit shortcut, and nothing pre-selects
     * approve.
     */
    @SerialName("default_to_no") val defaultToNo: Boolean,
    @SerialName("state") val state: CardState,
)

/** The head ask moved: the card waiting now, if any. */
@Serializable
data class AskMoved(
    @SerialName("card") val card: AskCard? = null,
)

@Serializable(with = AskRowSerializer::class)
sealed interface AskRow {
    /**
     * A plan the agent proposed, and what the person decided: its title,
     * lifted from an opening heading that names it, and the rest as its
     * body. While its first line is still being written there is no title
     * yet and nothing of that line in the body.
     */
    data class Plan(
        val body: Markdown,
        val verdict: PlanVerdict,
        val mode: String,
        val modeName: String,
        val writing: Boolean,
        val note: String? = null,
        val title: String? = null,
    ) : AskRow
    /**
     * Questions asked as the work, then the answers sent: "answered 2 of
     * 3", or the person's own words when they replied instead.
     */
    data class Questions(
        val questions: List<QuestionView>,
        val answers: List<AnswerView>,
        val skipped: Int,
        val resolution: Resolution,
        val reply: String? = null,
    ) : AskRow
    /** A tool server's form: "Sent 3 fields to github". */
    data class Form(
        val server: String,
        val message: String,
        val fields: List<String>,
        val resolution: Resolution,
    ) : AskRow
    /** A tool server's link to open. */
    data class Link(
        val server: String,
        val message: String,
        val url: String,
        val resolution: Resolution,
    ) : AskRow
    /**
     * Files and network beyond the sandbox: "Granted write target/ this
     * turn".
     */
    data class Grant(
        val reason: String,
        val read: List<String>,
        val write: List<String>,
        val network: Boolean,
        val hosts: List<String>,
        val resolution: Resolution,
        val granted: Granted? = null,
    ) : AskRow
    /**
     * A dialog the provider showed that this build could not read: it was
     * answered in the provider's own terminal or ended by a stop.
     */
    data class Unanswerable(
        val reason: String,
        val resolution: Resolution,
    ) : AskRow
}

