                "Fetching" -> BlobStatus.Fetching
                "Ready" -> BlobStatus.Ready
                else -> throw SerializationException("no BlobStatus is named ${element.content}")
            }
        }
        val obj = element as? JsonObject
            ?: throw SerializationException("BlobStatus must be a string or object")
        if (obj.size != 1) {
            throw SerializationException("BlobStatus names exactly one variant")
        }
        val (tag, payload) = obj.entries.first()
        val json = jsonDecoder.json
        return when (tag) {
            "Failed" -> BlobStatus.Failed(json.decodeFromJsonElement(serializer<String>(), payload))
            else -> throw SerializationException("unknown BlobStatus variant $tag")
