/**
 * Where the card is after the person acts. Stop is in the menu while a
 * turn runs: it is the interrupt, and the agent stays.
 */
@Serializable(with = CardStateSerializer::class)
sealed interface CardState {
    data object Open : CardState
    /** Shrunk to one line until the agent confirms. */
    data object Sending : CardState
    /** The card is back, with why the answer was refused. */
    data class Rejected(val value: Refusal) : CardState
    /** The connection dropped before a reply: resend or discard. */
    data object NotConfirmed : CardState
    /** The agent exited with the ask open. */
    data object Dismissed : CardState
}

object CardStateSerializer : KSerializer<CardState> {
    override val descriptor: SerialDescriptor =
        buildClassSerialDescriptor("sh.amux.values.CardState")

    override fun deserialize(decoder: Decoder): CardState {
        val jsonDecoder = decoder as? JsonDecoder
            ?: throw SerializationException("CardState requires Json")
        val element = jsonDecoder.decodeJsonElement()
        if (element is JsonPrimitive && element.isString) {
            return when (element.content) {
                "Open" -> CardState.Open
                "Sending" -> CardState.Sending
                "NotConfirmed" -> CardState.NotConfirmed
                "Dismissed" -> CardState.Dismissed
                else -> throw SerializationException("no CardState is named ${element.content}")
            }
        }
        val obj = element as? JsonObject
            ?: throw SerializationException("CardState must be a string or object")
        if (obj.size != 1) {
            throw SerializationException("CardState names exactly one variant")
        }
        val (tag, payload) = obj.entries.first()
        val json = jsonDecoder.json
        return when (tag) {
            "Rejected" -> CardState.Rejected(json.decodeFromJsonElement(serializer<Refusal>(), payload))
            else -> throw SerializationException("unknown CardState variant $tag")
        }
    }

    override fun serialize(encoder: Encoder, value: CardState) {
        val jsonEncoder = encoder as? JsonEncoder
            ?: throw SerializationException("CardState requires Json")
        val json = jsonEncoder.json
        val element: JsonElement = when (value) {
            CardState.Open -> JsonPrimitive("Open")
            CardState.Sending -> JsonPrimitive("Sending")
            is CardState.Rejected -> JsonObject(
                mapOf("Rejected" to json.encodeToJsonElement(serializer<Refusal>(), value.value)),
            )
            CardState.NotConfirmed -> JsonPrimitive("NotConfirmed")
            CardState.Dismissed -> JsonPrimitive("Dismissed")
        }
        jsonEncoder.encodeJsonElement(element)
    }
