/**
 * An act on an open chat. Its answer is a `SendOutcome` for `Send` and
 * `SendWithReview` (as `{"Ok": SendOutcome}`), a `CommandOutcome` for
 * `Command`, a `SendOutcome`
 * or null for `Resend`, a `PageOutcome` for `PageOlder`, and an
 * `ActOutcome` for every other.
 */
@Serializable(with = ChatActSerializer::class)
sealed interface ChatAct {
    data class Send(val value: Draft) : ChatAct
    /**
     * Sends the draft with the review's drafts after its words, as the
     * review's text attachment naming exactly those comments: the round
     * closes when the agent's host accepts the message. Answers
     * `{"Ok": SendOutcome}`, or `{"Err": ..}` without sending when the
     * review cannot be read or holds no drafts.
     */
    data class SendWithReview(val value: Draft) : ChatAct
    /**
     * A draft that names a command the client handles itself (`/model`,
     * `/effort`, `/rename`) or one the agent does not run; the outcome's
     * `Send` says to send it as typed.
     */
    data class Command(val value: Draft) : ChatAct
    /**
     * Answers the head ask, named by its key, with the choice at `choice`
     * on its card; `note` goes back with a choice that takes one.
     */
    data class Answer(
        val ask: String,
        val choice: Int,
        val note: String,
    ) : ChatAct
    /**
     * Submits the head form ask with one value per field, in the form's
     * order; the shared view checks and encodes them.
     */
    data class AnswerForm(
        val ask: String,
        val values: List<FormValue>,
    ) : ChatAct
    /** Answers the head question ask with one response per question. */
    data class AnswerQuestions(
        val ask: String,
        val responses: List<QuestionResponse>,
    ) : ChatAct
    /**
     * Replies to the head question ask in the person's own words instead,
     * with what they had answered so far.
     */
    data class ReplyInstead(
        val ask: String,
        val reply: String,
        val soFar: List<QuestionResponse>,
    ) : ChatAct
    /** A pick from the settings view. */
    data class ChangeSetting(val value: SettingChange) : ChatAct
    /** Takes a queued prompt, by input id, back out of the queue. */
    data class Withdraw(val value: List<Int>) : ChatAct
    /** Steers a queued prompt into the running turn. */
    data class SendNow(val value: List<Int>) : ChatAct
    /** Sends a not-confirmed input again under a new id. */
    data class Resend(val value: List<Int>) : ChatAct
    /** Stops the agent's turn; the agent stays. */
    data object Interrupt : ChatAct
    /**
     * Stops one background job by the key its `JobStop` gives: a job in
     * the overview, or a provider subagent's own, which its composer's
     * `Native` mode offers.
     */
    data class StopJob(val value: String) : ChatAct
    /**
     * Takes terminal Claude's own view back to the agent's conversation
     * after it switched to another.
     */
    data object SwitchBack : ChatAct
    /**
     * The exited composer's one tap: resumes the agent with the draft as
     * its first prompt; on anything but Done the draft stays the
     * composer's.
     */
    data class Resume(val value: Draft) : ChatAct
    /**
     * Up to this many rows older than the oldest held; they arrive below
     * the oldest.
     */
    data class PageOlder(val value: Int) : ChatAct
}

