 * when it moved.
 */
@Serializable
data class ChatDelta(
    /** The chat's id within its fleet. */
    @SerialName("chat") val chat: Long,
    /**
     * The rows that changed among those the host held, each run folded as
     * the reader left it. A row new at either edge, or held through a
     * reload, is read when it is drawn.
     */
    @SerialName("rows") val rows: List<Row>,
    /**
     * How each agent the held rows open stands, from the fleet, and what
     * each group of them comes to: a row that opens an agent draws its
     * state from here, since the fleet moving changes no row.
     */
    @SerialName("agents") val agents: ChatAgents? = null,
    @SerialName("ask") val ask: AskMoved? = null,
    @SerialName("frame") val frame: ChatFrame? = null,
    @SerialName("keys") val keys: KeysMoved? = null,
    @SerialName("overview") val overview: Overview? = null,
    /**
     * The review page open on the chat, whole, when it moved: the rows an
     * anchor's indices count are those of the page handed over last.
     */
    @SerialName("review") val review: ReviewPage? = null,
    @SerialName("settings") val settings: SettingsView? = null,
)

