                "OpenLink" -> ChoiceOutcome.OpenLink
                "GrantForTurn" -> ChoiceOutcome.GrantForTurn
                "GrantForSession" -> ChoiceOutcome.GrantForSession
                "Deny" -> ChoiceOutcome.Deny
                else -> throw SerializationException("no ChoiceOutcome is named ${element.content}")
            }
        }
        val obj = element as? JsonObject
            ?: throw SerializationException("ChoiceOutcome must be a string or object")
        if (obj.size != 1) {
            throw SerializationException("ChoiceOutcome names exactly one variant")
        }
        val (tag, payload) = obj.entries.first()
        val json = jsonDecoder.json
        return when (tag) {
            "AllowAlways" -> {
                val fields = payload as? JsonObject
                    ?: throw SerializationException("ChoiceOutcome.AllowAlways payload must be an object")
                ChoiceOutcome.AllowAlways(
                    subjects = json.decodeFromJsonElement(
                        serializer<List<String>>(),
                        fields["subjects"] ?: throw SerializationException("ChoiceOutcome.AllowAlways missing field subjects"),
                    ),
                    directories = json.decodeFromJsonElement(
                        serializer<List<String>>(),
                        fields["directories"] ?: throw SerializationException("ChoiceOutcome.AllowAlways missing field directories"),
                    ),
                    mode = json.decodeFromJsonElement(
                        serializer<String>(),
                        fields["mode"] ?: throw SerializationException("ChoiceOutcome.AllowAlways missing field mode"),
                    ),
                    modeName = json.decodeFromJsonElement(
                        serializer<String>(),
                        fields["mode_name"] ?: throw SerializationException("ChoiceOutcome.AllowAlways missing field mode_name"),
                    ),
                    scope = json.decodeFromJsonElement(
                        serializer<Scope>(),
                        fields["scope"] ?: throw SerializationException("ChoiceOutcome.AllowAlways missing field scope"),
                    ),
                )
            }
            "AllowSimilar" -> {
                val fields = payload as? JsonObject
                    ?: throw SerializationException("ChoiceOutcome.AllowSimilar payload must be an object")
                ChoiceOutcome.AllowSimilar(
                    prefix = json.decodeFromJsonElement(
                        serializer<List<String>>(),
                        fields["prefix"] ?: throw SerializationException("ChoiceOutcome.AllowSimilar missing field prefix"),
                    ),
                )
            }
            "AllowNetwork" -> {
                val fields = payload as? JsonObject
                    ?: throw SerializationException("ChoiceOutcome.AllowNetwork payload must be an object")
                ChoiceOutcome.AllowNetwork(
                    hosts = json.decodeFromJsonElement(
                        serializer<List<String>>(),
                        fields["hosts"] ?: throw SerializationException("ChoiceOutcome.AllowNetwork missing field hosts"),
                    ),
                )
            }
            "ApprovePlan" -> {
                val fields = payload as? JsonObject
                    ?: throw SerializationException("ChoiceOutcome.ApprovePlan payload must be an object")
                ChoiceOutcome.ApprovePlan(
                    mode = json.decodeFromJsonElement(
                        serializer<String>(),
                        fields["mode"] ?: throw SerializationException("ChoiceOutcome.ApprovePlan missing field mode"),
                    ),
                    modeName = json.decodeFromJsonElement(
                        serializer<String>(),
                        fields["mode_name"] ?: throw SerializationException("ChoiceOutcome.ApprovePlan missing field mode_name"),
                    ),
                )
            }
            else -> throw SerializationException("unknown ChoiceOutcome variant $tag")
        }
    }

    override fun serialize(encoder: Encoder, value: ChoiceOutcome) {
        val jsonEncoder = encoder as? JsonEncoder
            ?: throw SerializationException("ChoiceOutcome requires Json")
        val json = jsonEncoder.json
        val element: JsonElement = when (value) {
            ChoiceOutcome.AllowOnce -> JsonPrimitive("AllowOnce")
            ChoiceOutcome.AllowForSession -> JsonPrimitive("AllowForSession")
            ChoiceOutcome.DenyAndStop -> JsonPrimitive("DenyAndStop")
            ChoiceOutcome.SendBack -> JsonPrimitive("SendBack")
            ChoiceOutcome.Submit -> JsonPrimitive("Submit")
            ChoiceOutcome.Decline -> JsonPrimitive("Decline")
            ChoiceOutcome.OpenLink -> JsonPrimitive("OpenLink")
            ChoiceOutcome.GrantForTurn -> JsonPrimitive("GrantForTurn")
            ChoiceOutcome.GrantForSession -> JsonPrimitive("GrantForSession")
            is ChoiceOutcome.AllowAlways -> JsonObject(
                mapOf(
                    "AllowAlways" to buildJsonObject {
                        put("subjects", json.encodeToJsonElement(serializer<List<String>>(), value.subjects))
                        put("directories", json.encodeToJsonElement(serializer<List<String>>(), value.directories))
                        put("mode", json.encodeToJsonElement(serializer<String>(), value.mode))
                        put("mode_name", json.encodeToJsonElement(serializer<String>(), value.modeName))
                        put("scope", json.encodeToJsonElement(serializer<Scope>(), value.scope))
                    },
                ),
            )
            is ChoiceOutcome.AllowSimilar -> JsonObject(
                mapOf(
                    "AllowSimilar" to buildJsonObject {
                        put("prefix", json.encodeToJsonElement(serializer<List<String>>(), value.prefix))
                    },
                ),
            )
            is ChoiceOutcome.AllowNetwork -> JsonObject(
                mapOf(
                    "AllowNetwork" to buildJsonObject {
                        put("hosts", json.encodeToJsonElement(serializer<List<String>>(), value.hosts))
                    },
                ),
            )
            ChoiceOutcome.Deny -> JsonPrimitive("Deny")
            is ChoiceOutcome.ApprovePlan -> JsonObject(
                mapOf(
                    "ApprovePlan" to buildJsonObject {
                        put("mode", json.encodeToJsonElement(serializer<String>(), value.mode))
                        put("mode_name", json.encodeToJsonElement(serializer<String>(), value.modeName))
                    },
                ),
            )
        }
        jsonEncoder.encodeJsonElement(element)
    }
}

