/**
 * What the client did with a draft that names a command it runs itself
 * (`/model`, `/effort`, `/rename`), or one the agent does not run.
 */
@Serializable(with = CommandOutcomeSerializer::class)
sealed interface CommandOutcome {
    /** Not a command the client runs: send the draft as typed. */
    data object Send : CommandOutcome
    /** A bare `/model` or `/effort`: open amux's own picker for it. */
    data class Pick(val value: ClientCommand) : CommandOutcome
    /** A bare `/rename`: ask for the agent's new name. */
    data object AskName : CommandOutcome
    /** A setting set or the agent renamed, or how that failed. */
    data class Acted(val value: ActOutcome) : CommandOutcome
    /**
     * The pick went as the agent's own command, typed (terminal Claude's
     * model and effort): a prompt, as any other.
     */
    data class Sent(val value: SendOutcome) : CommandOutcome
    /**
     * The agent does not run this command, and it was not sent: Codex
     * runs only the commands amux implements for it. `offered` is what it
     * does run; `hint` is the mention to type when the name is a skill.
     */
    data class Refused(
        val command: String,
        val offered: List<String>,
        val hint: String? = null,
    ) : CommandOutcome
    /** The command names a model or effort the agent does not offer. */
    data class Unknown(
        val command: ClientCommand,
        val value: String,
        val offered: List<String>,
    ) : CommandOutcome
}

object CommandOutcomeSerializer : KSerializer<CommandOutcome> {
    override val descriptor: SerialDescriptor =
        buildClassSerialDescriptor("sh.amux.values.CommandOutcome")

    override fun deserialize(decoder: Decoder): CommandOutcome {
        val jsonDecoder = decoder as? JsonDecoder
            ?: throw SerializationException("CommandOutcome requires Json")
        val element = jsonDecoder.decodeJsonElement()
        if (element is JsonPrimitive && element.isString) {
            return when (element.content) {
                "Send" -> CommandOutcome.Send
                "AskName" -> CommandOutcome.AskName
                else -> throw SerializationException("no CommandOutcome is named ${element.content}")
            }
        }
        val obj = element as? JsonObject
            ?: throw SerializationException("CommandOutcome must be a string or object")
        if (obj.size != 1) {
            throw SerializationException("CommandOutcome names exactly one variant")
        }
        val (tag, payload) = obj.entries.first()
        val json = jsonDecoder.json
        return when (tag) {
            "Pick" -> CommandOutcome.Pick(json.decodeFromJsonElement(serializer<ClientCommand>(), payload))
            "Acted" -> CommandOutcome.Acted(json.decodeFromJsonElement(serializer<ActOutcome>(), payload))
            "Sent" -> CommandOutcome.Sent(json.decodeFromJsonElement(serializer<SendOutcome>(), payload))
            "Refused" -> {
                val fields = payload as? JsonObject
                    ?: throw SerializationException("CommandOutcome.Refused payload must be an object")
                CommandOutcome.Refused(
                    command = json.decodeFromJsonElement(
                        serializer<String>(),
                        fields["command"] ?: throw SerializationException("CommandOutcome.Refused missing field command"),
                    ),
                    offered = json.decodeFromJsonElement(
                        serializer<List<String>>(),
                        fields["offered"] ?: throw SerializationException("CommandOutcome.Refused missing field offered"),
                    ),
                    hint = fields["hint"]?.takeUnless { it is JsonNull }?.let {
                        json.decodeFromJsonElement(serializer<String>(), it)
                    },
                )
            }
            "Unknown" -> {
                val fields = payload as? JsonObject
                    ?: throw SerializationException("CommandOutcome.Unknown payload must be an object")
                CommandOutcome.Unknown(
                    command = json.decodeFromJsonElement(
                        serializer<ClientCommand>(),
                        fields["command"] ?: throw SerializationException("CommandOutcome.Unknown missing field command"),
                    ),
                    value = json.decodeFromJsonElement(
                        serializer<String>(),
                        fields["value"] ?: throw SerializationException("CommandOutcome.Unknown missing field value"),
                    ),
                    offered = json.decodeFromJsonElement(
                        serializer<List<String>>(),
                        fields["offered"] ?: throw SerializationException("CommandOutcome.Unknown missing field offered"),
                    ),
                )
            }
            else -> throw SerializationException("unknown CommandOutcome variant $tag")
        }
    }

    override fun serialize(encoder: Encoder, value: CommandOutcome) {
        val jsonEncoder = encoder as? JsonEncoder
            ?: throw SerializationException("CommandOutcome requires Json")
        val json = jsonEncoder.json
        val element: JsonElement = when (value) {
            CommandOutcome.Send -> JsonPrimitive("Send")
            is CommandOutcome.Pick -> JsonObject(
                mapOf("Pick" to json.encodeToJsonElement(serializer<ClientCommand>(), value.value)),
            )
            CommandOutcome.AskName -> JsonPrimitive("AskName")
            is CommandOutcome.Acted -> JsonObject(
                mapOf("Acted" to json.encodeToJsonElement(serializer<ActOutcome>(), value.value)),
            )
            is CommandOutcome.Sent -> JsonObject(
                mapOf("Sent" to json.encodeToJsonElement(serializer<SendOutcome>(), value.value)),
            )
            is CommandOutcome.Refused -> JsonObject(
                mapOf(
                    "Refused" to buildJsonObject {
                        put("command", json.encodeToJsonElement(serializer<String>(), value.command))
                        put("offered", json.encodeToJsonElement(serializer<List<String>>(), value.offered))
                        value.hint?.let {
                            put("hint", json.encodeToJsonElement(serializer<String>(), it))
                        }
                    },
                ),
            )
            is CommandOutcome.Unknown -> JsonObject(
                mapOf(
                    "Unknown" to buildJsonObject {
                        put("command", json.encodeToJsonElement(serializer<ClientCommand>(), value.command))
                        put("value", json.encodeToJsonElement(serializer<String>(), value.value))
                        put("offered", json.encodeToJsonElement(serializer<List<String>>(), value.offered))
                    },
                ),
            )
        }
        jsonEncoder.encodeJsonElement(element)
    }
}

