/** What the composer offers. */
@Serializable(with = ComposerSerializer::class)
sealed interface Composer {
    data object Send : Composer
    /**
     * The agent has exited: the draft goes through ResumeAgent as the new
     * incarnation's first prompt, one tap.
     */
    data object Resume : Composer
    /**
     * The chat is not current. Drafting continues; a send is refused at
     * once and the draft stays in the composer, which says why.
     */
    data class Waiting(val value: sh.amux.values.Waiting) : Composer
    /**
     * A subagent its parent's provider runs (Claude's Agent tool, a Codex
     * child thread): neither provider lets anyone but the parent's model
     * talk to it, so there is no text box, only what says so and, where
     * the provider stops one subagent on request, its Stop. `stop` is the
     * subagent's own job as its snapshot lists it; an ask in its chat is
     * answered as any ask is.
     */
    data class Native(
        val stop: JobStop,
    ) : Composer
}

object ComposerSerializer : KSerializer<Composer> {
    override val descriptor: SerialDescriptor =
        buildClassSerialDescriptor("sh.amux.values.Composer")

    override fun deserialize(decoder: Decoder): Composer {
        val jsonDecoder = decoder as? JsonDecoder
            ?: throw SerializationException("Composer requires Json")
        val element = jsonDecoder.decodeJsonElement()
        if (element is JsonPrimitive && element.isString) {
            return when (element.content) {
                "Send" -> Composer.Send
                "Resume" -> Composer.Resume
                else -> throw SerializationException("no Composer is named ${element.content}")
            }
        }
        val obj = element as? JsonObject
            ?: throw SerializationException("Composer must be a string or object")
        if (obj.size != 1) {
            throw SerializationException("Composer names exactly one variant")
        }
        val (tag, payload) = obj.entries.first()
        val json = jsonDecoder.json
        return when (tag) {
            "Waiting" -> Composer.Waiting(json.decodeFromJsonElement(serializer<Waiting>(), payload))
            "Native" -> {
                val fields = payload as? JsonObject
                    ?: throw SerializationException("Composer.Native payload must be an object")
                Composer.Native(
                    stop = json.decodeFromJsonElement(
                        serializer<JobStop>(),
                        fields["stop"] ?: throw SerializationException("Composer.Native missing field stop"),
                    ),
                )
            }
            else -> throw SerializationException("unknown Composer variant $tag")
        }
    }

    override fun serialize(encoder: Encoder, value: Composer) {
        val jsonEncoder = encoder as? JsonEncoder
            ?: throw SerializationException("Composer requires Json")
        val json = jsonEncoder.json
        val element: JsonElement = when (value) {
            Composer.Send -> JsonPrimitive("Send")
            Composer.Resume -> JsonPrimitive("Resume")
            is Composer.Waiting -> JsonObject(
                mapOf("Waiting" to json.encodeToJsonElement(serializer<Waiting>(), value.value)),
            )
            is Composer.Native -> JsonObject(
                mapOf(
                    "Native" to buildJsonObject {
                        put("stop", json.encodeToJsonElement(serializer<JobStop>(), value.stop))
                    },
                ),
            )
        }
        jsonEncoder.encodeJsonElement(element)
    }
}

