            is KeysMoved.Edges -> JsonObject(
                mapOf(
                    "Edges" to buildJsonObject {
                        put("above", json.encodeToJsonElement(serializer<List<String>>(), value.above))
                        put("below", json.encodeToJsonElement(serializer<List<String>>(), value.below))
                        put("dropped", json.encodeToJsonElement(serializer<Int>(), value.dropped))
                    },
                ),
            )
        }
        jsonEncoder.encodeJsonElement(element)
    }
}

