/** What a client tells the daemon of setting up. */
@Serializable(with = OnboardingAnswerSerializer::class)
sealed interface OnboardingAnswer {
    /** The step is on screen: counted, nothing kept. */
    data class Shown(val value: SetupStep) : OnboardingAnswer
    /**
     * The person confirmed a step only they can confirm: keeping it
     * reachable, the repositories, helping improve amux.
     */
    data class Done(val value: SetupStep) : OnboardingAnswer
    /** "Later". */
    data class Skip(val value: SetupStep) : OnboardingAnswer
    /** "Finish setting up" dismissed: every step still needed is skipped. */
    data object Dismiss : OnboardingAnswer
    /** A one-tap sign-in was put in front of the person, on this side. */
    data class SignInOfferShown(val value: OfferRole) : OnboardingAnswer
}

object OnboardingAnswerSerializer : KSerializer<OnboardingAnswer> {
    override val descriptor: SerialDescriptor =
        buildClassSerialDescriptor("sh.amux.values.OnboardingAnswer")

    override fun deserialize(decoder: Decoder): OnboardingAnswer {
        val jsonDecoder = decoder as? JsonDecoder
            ?: throw SerializationException("OnboardingAnswer requires Json")
        val element = jsonDecoder.decodeJsonElement()
        if (element is JsonPrimitive && element.isString) {
            return when (element.content) {
                "Dismiss" -> OnboardingAnswer.Dismiss
                else -> throw SerializationException("no OnboardingAnswer is named ${element.content}")
            }
        }
        val obj = element as? JsonObject
            ?: throw SerializationException("OnboardingAnswer must be a string or object")
        if (obj.size != 1) {
            throw SerializationException("OnboardingAnswer names exactly one variant")
        }
        val (tag, payload) = obj.entries.first()
        val json = jsonDecoder.json
        return when (tag) {
            "Shown" -> OnboardingAnswer.Shown(json.decodeFromJsonElement(serializer<SetupStep>(), payload))
            "Done" -> OnboardingAnswer.Done(json.decodeFromJsonElement(serializer<SetupStep>(), payload))
            "Skip" -> OnboardingAnswer.Skip(json.decodeFromJsonElement(serializer<SetupStep>(), payload))
            "SignInOfferShown" -> OnboardingAnswer.SignInOfferShown(json.decodeFromJsonElement(serializer<OfferRole>(), payload))
            else -> throw SerializationException("unknown OnboardingAnswer variant $tag")
        }
    }

    override fun serialize(encoder: Encoder, value: OnboardingAnswer) {
        val jsonEncoder = encoder as? JsonEncoder
            ?: throw SerializationException("OnboardingAnswer requires Json")
        val json = jsonEncoder.json
        val element: JsonElement = when (value) {
            is OnboardingAnswer.Shown -> JsonObject(
                mapOf("Shown" to json.encodeToJsonElement(serializer<SetupStep>(), value.value)),
            )
            is OnboardingAnswer.Done -> JsonObject(
                mapOf("Done" to json.encodeToJsonElement(serializer<SetupStep>(), value.value)),
            )
            is OnboardingAnswer.Skip -> JsonObject(
                mapOf("Skip" to json.encodeToJsonElement(serializer<SetupStep>(), value.value)),
            )
            OnboardingAnswer.Dismiss -> JsonPrimitive("Dismiss")
            is OnboardingAnswer.SignInOfferShown -> JsonObject(
                mapOf("SignInOfferShown" to json.encodeToJsonElement(serializer<OfferRole>(), value.value)),
            )
        }
        jsonEncoder.encodeJsonElement(element)
    }
}

