/**
 * Pairing with a machine: the PIN its person reads out, or the link its
 * QR code carries.
 */
@Serializable(with = PairRequestSerializer::class)
sealed interface PairRequest {
    data class Pin(
        val pin: String,
        val addrs: List<String>,
        val hostId: List<Int>? = null,
    ) : PairRequest
    data class Link(val value: String) : PairRequest
}

object PairRequestSerializer : KSerializer<PairRequest> {
    override val descriptor: SerialDescriptor =
        buildClassSerialDescriptor("sh.amux.values.PairRequest")

    override fun deserialize(decoder: Decoder): PairRequest {
        val jsonDecoder = decoder as? JsonDecoder
            ?: throw SerializationException("PairRequest requires Json")
        val element = jsonDecoder.decodeJsonElement()
        val obj = element as? JsonObject
            ?: throw SerializationException("PairRequest must be an object")
        if (obj.size != 1) {
            throw SerializationException("PairRequest names exactly one variant")
        }
        val (tag, payload) = obj.entries.first()
        val json = jsonDecoder.json
        return when (tag) {
            "Pin" -> {
                val fields = payload as? JsonObject
                    ?: throw SerializationException("PairRequest.Pin payload must be an object")
                PairRequest.Pin(
                    pin = json.decodeFromJsonElement(
                        serializer<String>(),
                        fields["pin"] ?: throw SerializationException("PairRequest.Pin missing field pin"),
                    ),
                    addrs = json.decodeFromJsonElement(
                        serializer<List<String>>(),
                        fields["addrs"] ?: throw SerializationException("PairRequest.Pin missing field addrs"),
                    ),
                    hostId = fields["host_id"]?.takeUnless { it is JsonNull }?.let {
                        json.decodeFromJsonElement(serializer<List<Int>>(), it)
                    },
                )
            }
            "Link" -> PairRequest.Link(json.decodeFromJsonElement(serializer<String>(), payload))
            else -> throw SerializationException("unknown PairRequest variant $tag")
        }
    }

    override fun serialize(encoder: Encoder, value: PairRequest) {
        val jsonEncoder = encoder as? JsonEncoder
            ?: throw SerializationException("PairRequest requires Json")
        val json = jsonEncoder.json
        val element: JsonElement = when (value) {
            is PairRequest.Pin -> JsonObject(
                mapOf(
                    "Pin" to buildJsonObject {
                        put("pin", json.encodeToJsonElement(serializer<String>(), value.pin))
                        put("addrs", json.encodeToJsonElement(serializer<List<String>>(), value.addrs))
                        value.hostId?.let {
                            put("host_id", json.encodeToJsonElement(serializer<List<Int>>(), it))
                        }
                    },
                ),
            )
            is PairRequest.Link -> JsonObject(
                mapOf("Link" to json.encodeToJsonElement(serializer<String>(), value.value)),
            )
        }
        jsonEncoder.encodeJsonElement(element)
    }
}

