            ?: throw SerializationException("Reach must be a string or object")
        if (obj.size != 1) {
            throw SerializationException("Reach names exactly one variant")
        }
        val (tag, payload) = obj.entries.first()
        val json = jsonDecoder.json
        return when (tag) {
            "Online" -> Reach.Online(json.decodeFromJsonElement(serializer<RouteKind>(), payload))
            "Offline" -> Reach.Offline(json.decodeFromJsonElement(serializer<Offline>(), payload))
            else -> throw SerializationException("unknown Reach variant $tag")
        }
    }

    override fun serialize(encoder: Encoder, value: Reach) {
        val jsonEncoder = encoder as? JsonEncoder
            ?: throw SerializationException("Reach requires Json")
        val json = jsonEncoder.json
        val element: JsonElement = when (value) {
