            )
            Reach.Away -> JsonPrimitive("Away")
            is Reach.Offline -> JsonObject(
                mapOf("Offline" to json.encodeToJsonElement(serializer<Offline>(), value.value)),
            )
        }
        jsonEncoder.encodeJsonElement(element)
    }
}

