/** A row's place in its run. */
@Serializable
data class Run(
    /**
     * The run's oldest held step, where an opened run draws its header.
     * It moves as the window's low edge does, so it names no run: hold
     * an open run by a member (see [`run_is_open`]).
     */
    @SerialName("first") val first: String,
    /** Its newest step, where a folded run draws its one line. */
    @SerialName("last") val last: String,
    @SerialName("steps") val steps: Int,
    /** Nothing but steps follows it yet: the agent is still at it. */
    @SerialName("live") val live: Boolean,
    /**
     * It starts at the oldest held rows and older history exists, so it may
     * continue below: its counts are a floor.
     */
    @SerialName("open_below") val openBelow: Boolean,
    /**
     * While the run is under way this step shows: it is the newest, or it
     * is still running. False once the run is over.
     */
    @SerialName("live_shown") val liveShown: Boolean,
    /**
     * This step failed and nothing later in its turn redid it, and the
     * turn has ended: it stays in view when the run folds.
     */
    @SerialName("unresolved_failure") val unresolvedFailure: Boolean,
    /**
     * The reader opened it: a folding view's open set holds one of its
     * steps. Always false for a view that does not fold.
     */
    @SerialName("open") val open: Boolean,
    /** What the run's steps did, on its newest step's row only. */
    @SerialName("counts") val counts: RunCounts? = null,
    /**
     * On the oldest step a live run shows, what the steps it does not
     * show did, for the line above it; absent elsewhere, and when it shows
     * every step.
     */
    @SerialName("hidden") val hidden: RunCounts? = null,
    /**
     * For one of the run's two newest steps, how many steps follow it
     * (none for the newest); absent for the rest.
     */
    @SerialName("recent") val recent: Int? = null,
)

/** What a run's steps did. */
@Serializable
data class RunCounts(
    @SerialName("commands") val commands: Int,
    /** Files changed, each counted once however often it changed. */
    @SerialName("edits") val edits: Int,
    /** Files read, each counted once however often it was read. */
    @SerialName("reads") val reads: Int,
    /** Searches of files or the web. */
    @SerialName("searches") val searches: Int,
    /** Folders listed. */
    @SerialName("lists") val lists: Int,
    /** Pages fetched. */
    @SerialName("fetches") val fetches: Int,
    /** Subagents run, started or stopped. */
    @SerialName("subagents") val subagents: Int,
    /** Tool-server calls, images and the rest. */
    @SerialName("other") val other: Int,
)

@Serializable(with = ScopeSerializer::class)
sealed interface Scope {
    data object Session : Scope
    /** This project, for this person. */
    data object Project : Scope
    /** This project, shared with everyone who works on it. */
    data object ProjectShared : Scope
    /** Every project. */
    data object User : Scope
    data class Other(val value: String) : Scope
}

object ScopeSerializer : KSerializer<Scope> {
    override val descriptor: SerialDescriptor =
        buildClassSerialDescriptor("sh.amux.values.Scope")

    override fun deserialize(decoder: Decoder): Scope {
        val jsonDecoder = decoder as? JsonDecoder
            ?: throw SerializationException("Scope requires Json")
        val element = jsonDecoder.decodeJsonElement()
        if (element is JsonPrimitive && element.isString) {
            return when (element.content) {
                "Session" -> Scope.Session
                "Project" -> Scope.Project
                "ProjectShared" -> Scope.ProjectShared
                "User" -> Scope.User
                else -> throw SerializationException("no Scope is named ${element.content}")
            }
        }
        val obj = element as? JsonObject
            ?: throw SerializationException("Scope must be a string or object")
        if (obj.size != 1) {
            throw SerializationException("Scope names exactly one variant")
        }
        val (tag, payload) = obj.entries.first()
        val json = jsonDecoder.json
        return when (tag) {
            "Other" -> Scope.Other(json.decodeFromJsonElement(serializer<String>(), payload))
            else -> throw SerializationException("unknown Scope variant $tag")
        }
    }

    override fun serialize(encoder: Encoder, value: Scope) {
        val jsonEncoder = encoder as? JsonEncoder
            ?: throw SerializationException("Scope requires Json")
        val json = jsonEncoder.json
        val element: JsonElement = when (value) {
            Scope.Session -> JsonPrimitive("Session")
            Scope.Project -> JsonPrimitive("Project")
            Scope.ProjectShared -> JsonPrimitive("ProjectShared")
            Scope.User -> JsonPrimitive("User")
            is Scope.Other -> JsonObject(
                mapOf("Other" to json.encodeToJsonElement(serializer<String>(), value.value)),
            )
        }
        jsonEncoder.encodeJsonElement(element)
    }
}

/**
 * What a row says under its name, by the agent's state. What the agent is
 * working on is a fact for agents finding each other, not for this line.
