/** Which limit a usage window is, for a client to word. */
@Serializable(with = UsageLabelSerializer::class)
sealed interface UsageLabel {
    data object FiveHour : UsageLabel
    /** The weekly limit, or one model's weekly limit. */
    data class Weekly(
        val model: String? = null,
    ) : UsageLabel
    /** A window known only by its length, as Codex gives it. */
    data class Minutes(val value: Int) : UsageLabel
    /** A window known only by the provider's own name for it. */
    data class Named(val value: String) : UsageLabel
}

object UsageLabelSerializer : KSerializer<UsageLabel> {
    override val descriptor: SerialDescriptor =
        buildClassSerialDescriptor("sh.amux.values.UsageLabel")

    override fun deserialize(decoder: Decoder): UsageLabel {
        val jsonDecoder = decoder as? JsonDecoder
            ?: throw SerializationException("UsageLabel requires Json")
        val element = jsonDecoder.decodeJsonElement()
        if (element is JsonPrimitive && element.isString) {
            return when (element.content) {
                "FiveHour" -> UsageLabel.FiveHour
                else -> throw SerializationException("no UsageLabel is named ${element.content}")
            }
        }
        val obj = element as? JsonObject
            ?: throw SerializationException("UsageLabel must be a string or object")
        if (obj.size != 1) {
            throw SerializationException("UsageLabel names exactly one variant")
        }
        val (tag, payload) = obj.entries.first()
        val json = jsonDecoder.json
        return when (tag) {
            "Weekly" -> {
                val fields = payload as? JsonObject
                    ?: throw SerializationException("UsageLabel.Weekly payload must be an object")
                UsageLabel.Weekly(
                    model = fields["model"]?.takeUnless { it is JsonNull }?.let {
                        json.decodeFromJsonElement(serializer<String>(), it)
                    },
                )
            }
            "Minutes" -> UsageLabel.Minutes(json.decodeFromJsonElement(serializer<Int>(), payload))
            "Named" -> UsageLabel.Named(json.decodeFromJsonElement(serializer<String>(), payload))
            else -> throw SerializationException("unknown UsageLabel variant $tag")
        }
    }

    override fun serialize(encoder: Encoder, value: UsageLabel) {
        val jsonEncoder = encoder as? JsonEncoder
            ?: throw SerializationException("UsageLabel requires Json")
        val json = jsonEncoder.json
        val element: JsonElement = when (value) {
            UsageLabel.FiveHour -> JsonPrimitive("FiveHour")
            is UsageLabel.Weekly -> JsonObject(
                mapOf(
                    "Weekly" to buildJsonObject {
                        value.model?.let {
                            put("model", json.encodeToJsonElement(serializer<String>(), it))
                        }
                    },
                ),
            )
            is UsageLabel.Minutes -> JsonObject(
                mapOf("Minutes" to json.encodeToJsonElement(serializer<Int>(), value.value)),
            )
            is UsageLabel.Named -> JsonObject(
                mapOf("Named" to json.encodeToJsonElement(serializer<String>(), value.value)),
            )
        }
        jsonEncoder.encodeJsonElement(element)
    }
}

